import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent, VlLinkComponent } from '@domg-wc/components/atom';
import { VlProzaMessage, VlProzaMessagePreloader } from '@domg-wc/components/block';

registerWebComponents([VlProzaMessagePreloader, VlProzaMessage, VlButtonComponent, VlLinkComponent]);

// De preloader haalt alle berichten van het domein op met één GET proza/domein/{domain} (of vanaf base-url), een
// lijst van { code, tekst }, bv. [{ "code": "inline", "tekst": "Inline" }, { "code": "action", "tekst": "Action" }].
// vl-proza-message zoekt zijn bericht eerst in die cache; staat het er niet in, dan vraagt hij het apart op.

// Zonder het element kan je een domein ook zelf preloaden, met een optionele baseUrl als tweede argument:
// VlProzaMessagePreloader.preload('mockdomain');
